-- Supabase contract for sync.js payload; apply explicitly. JWT + RLS only; no service-role runtime.
create table if not exists public.memories(owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,workspace_id uuid not null,id text not null,kind text not null,title text not null default '',content text not null default '',source jsonb not null default '{}'::jsonb,metadata jsonb not null default '{}'::jsonb,media jsonb not null default '{}'::jsonb,content_sha256 text not null check(content_sha256 ~ '^[a-fA-F0-9]{64}$'),schema_version int not null default 1 check(schema_version=1),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,primary key(owner_id,workspace_id,id));
create table if not exists public.links(owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,workspace_id uuid not null,source_id text not null,target_id text not null,relation text not null,provenance jsonb not null default '{}'::jsonb,confidence double precision,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,primary key(owner_id,workspace_id,source_id,target_id,relation),foreign key(owner_id,workspace_id,source_id) references public.memories(owner_id,workspace_id,id),foreign key(owner_id,workspace_id,target_id) references public.memories(owner_id,workspace_id,id),check(confidence is null or confidence between 0 and 1));
create table if not exists public.bundles(owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,workspace_id uuid not null,bundle_id text not null,schema_version int not null default 1,node_count int not null check(node_count>=0),link_count int not null check(link_count>=0),content_sha256 text not null check(content_sha256 ~ '^[a-fA-F0-9]{64}$'),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(owner_id,workspace_id,bundle_id));
create index if not exists memories_workspace_updated on public.memories(workspace_id,updated_at,id); create index if not exists links_workspace_updated on public.links(workspace_id,updated_at,source_id,target_id);
alter table public.memories enable row level security; alter table public.links enable row level security; alter table public.bundles enable row level security;
drop policy if exists memories_owner_all on public.memories; create policy memories_owner_all on public.memories for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
drop policy if exists links_owner_all on public.links; create policy links_owner_all on public.links for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
drop policy if exists bundles_owner_all on public.bundles; create policy bundles_owner_all on public.bundles for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
grant select,insert,update,delete on public.memories,public.links,public.bundles to authenticated;
